DROP TABLE IF EXISTS "mail_attachments" CASCADE;
CREATE TABLE "mail_attachments" (
  "id" bigint NOT NULL DEFAULT nextval('mail_attachments_id_seq'::regclass),
  "mail_id" bigint NOT NULL,
  "file_name" character varying NOT NULL,
  "file_path" text NOT NULL,
  "file_size" bigint,
  "mime_type" character varying,
  "created_at" timestamp with time zone DEFAULT now(),
  "file_hash" character varying
);


DROP TABLE IF EXISTS "mail_templates" CASCADE;
CREATE TABLE "mail_templates" (
  "id" bigint NOT NULL DEFAULT nextval('mail_templates_id_seq'::regclass),
  "name" character varying NOT NULL,
  "subject" character varying NOT NULL,
  "body" text NOT NULL,
  "description" text,
  "is_global" boolean DEFAULT false,
  "created_by" uuid,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now()
);


